WHERE m.company_id = #{companyId}
AND m.reporting_year = #{year}

    AND m.reporting_year = SUBSTRING(#{period}, 1, 4)::INT
    AND m.period_value = SUBSTRING(#{period}, 6, 2)::INT

AND i.category::text = #{category}
AND m.status::text = #{status}
AND m.facility_id = #{facilityId}

    AND (i.title ILIKE '%' || #{search} || '%'
         OR i.indicator_code ILIKE '%' || #{search} || '%'
         OR COALESCE(f.facility_name, '기업 전체') ILIKE '%' || #{search} || '%')

AND m.status = 'APPROVED'

choose.otherwise:
SELECT DISTINCT m.reporting_year::TEXT || '-' || LPAD(m.period_value::TEXT, 2, '0')
FROM esg_metric_data m
JOIN esg_indicators i ON i.id = m.indicator_id
WHERE m.company_id = #{companyId}
AND i.category::text = #{category}
AND m.status::text = #{status}
AND m.facility_id = #{facilityId}
AND m.status = 'APPROVED'
ORDER BY 1 DESC

mapper.update:
UPDATE esg_metric_data
SET status = CAST(#{toStatus} AS data_status_enum),
    approver_user_id = CASE WHEN #{toStatus} = 'APPROVED' THEN #{userId} ELSE NULL END,
    reject_reason = #{rejectReason},
    updated_at = CURRENT_TIMESTAMP
WHERE company_id = #{companyId}
  AND id = #{id}
  AND status::text IN

      #{status}

mapper.select:
SELECT m.id
FROM esg_metric_data m
JOIN esg_indicators i ON i.id = m.indicator_id
WHERE m.company_id = #{companyId}
  AND m.reporting_year = SUBSTRING(#{period}, 1, 4)::INT
  AND m.period_value = SUBSTRING(#{period}, 6, 2)::INT
AND i.category::text = #{category}
  AND m.status::text IN

      #{status}

ORDER BY m.id

SELECT SUM(m.numerical_value)
FROM esg_metric_data m
JOIN esg_indicators i ON i.id = m.indicator_id
WHERE m.company_id = #{companyId}
  AND i.indicator_code = #{indicatorCode}
  AND m.status = 'APPROVED'
  AND (m.reporting_year * 100 + m.period_value) = (
      SELECT MAX(m2.reporting_year * 100 + m2.period_value)
      FROM esg_metric_data m2
      JOIN esg_indicators i2 ON i2.id = m2.indicator_id
      WHERE m2.company_id = #{companyId}
        AND i2.indicator_code = #{indicatorCode}
        AND m2.status = 'APPROVED'
        AND (m2.reporting_year * 100 + m2.period_value) < (SUBSTRING(#{period}, 1, 4)::INT * 100 + SUBSTRING(#{period}, 6, 2)::INT)
  )

